/* ── iônica wordmark ─────────────────────────────────────────────────────── */

function IonicaLogo() {
  return (
    <div className="flex items-center justify-center py-4 px-3" style={{ minHeight: 56 }}>
      <svg width="71" height="17" viewBox="0 0 71.1111 16.4103" fill="none">
        <path d={DSPaths.ionicaI} fill="#4E008E" />
        <path d={DSPaths.ionicaNica} fill="#FF7500" />
        <path d={DSPaths.ionicaO} fill="url(#sidebar-logo-gradient)" />
        <defs>
          <linearGradient id="sidebar-logo-gradient" gradientUnits="userSpaceOnUse" x1="5.38556" x2="24.0819" y1="8.28906" y2="8.28906">
            <stop stopColor="#4E008E" />
            <stop offset="0.5" stopColor="#FF0098" />
            <stop offset="1" stopColor="#FF7500" />
          </linearGradient>
        </defs>
      </svg>
    </div>
  );
}

/* ── Minha iônica icon (orange square + white logo) ─────────────────────── */

function MinhaIonicaIcon() {
  return (
    <div
      className="shrink-0 relative overflow-hidden"
      style={{ width: 24, height: 24, background: '#FF7500', borderRadius: 4 }}
    >
      <svg className="absolute inset-0" width="24" height="24" viewBox="0 0 24 24" fill="none">
        <path d={DSPaths.minhaIonicaMark} fill="#FFFCFF" />
      </svg>
    </div>
  );
}

/* ── Estuda.com icon (blue square + leaf) ────────────────────────────────── */

function EstudaIcon() {
  return (
    <div
      className="shrink-0 relative overflow-hidden"
      style={{ width: 24, height: 24, background: '#4FAEE5', borderRadius: 4 }}
    >
      {/* Simplified leaf icon matching DS */}
      <svg className="absolute" style={{ top: 1, left: 4 }} width="16" height="20" viewBox="0 0 16 20" fill="none">
        <path d="M8 0.5L10 5.5L15.5 7L12 11L13 16.5L8 14L3 16.5L4 11L0.5 7L6 5.5L8 0.5Z" fill="#F2E3FF" fillOpacity="0.8" />
        <path d="M8 3L9.5 6.5L13 7.5L10.5 10L11.2 13.5L8 12L4.8 13.5L5.5 10L3 7.5L6.5 6.5L8 3Z" fill="#C6D93B" fillOpacity="0.9" />
      </svg>
    </div>
  );
}

/* ── Nav item (horizontal: accent bar + icon + label) ────────────────────── */

interface NavItemRowProps {
  label: string;
  icon: React.ReactNode;
  active?: boolean;
}

function NavItemRow({ label, icon, active = false }: NavItemRowProps) {
  return (
    <div className="relative flex w-full shrink-0" style={{ height: 72 }}>
      {/* Left purple accent bar */}
      <div
        style={{
          width: 2,
          height: '100%',
          background: active ? '#8600F4' : 'transparent',
          borderRadius: '0 2px 2px 0',
          flexShrink: 0,
        }}
      />
      {/* Row content */}
      <div
        className="flex flex-1 items-center gap-2 px-2 py-2"
        style={{
          background: active ? '#F2E3FF' : 'transparent',
        }}
      >
        <div className="shrink-0 flex items-center justify-center" style={{ width: 24, height: 24 }}>
          {icon}
        </div>
        <span
          style={{
            fontFamily: 'Plus Jakarta Sans, sans-serif',
            fontWeight: 600,
            fontSize: 12,
            color: active ? '#8600F4' : '#494150',
            lineHeight: 1.32,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
          }}
        >
          {label}
        </span>
      </div>
    </div>
  );
}

/* ── Bottom nav item (icon + label, smaller) ─────────────────────────────── */

function BottomNavItem({
  label,
  icon,
  badge,
}: {
  label: string;
  icon: React.ReactNode;
  badge?: number;
}) {
  return (
    <button
      className="relative flex items-center gap-2 w-full px-2 py-2 border-0 bg-transparent cursor-pointer transition-colors rounded-lg hover:bg-[#F6F0FB]"
      style={{ height: 40 }}
    >
      <div className="relative shrink-0 flex items-center justify-center" style={{ width: 20, height: 20 }}>
        {icon}
        {badge !== undefined && (
          <div
            className="absolute flex items-center justify-center"
            style={{
              width: 14,
              height: 14,
              background: '#FF0098',
              borderRadius: '50%',
              top: -5,
              right: -6,
            }}
          >
            <span style={{ fontFamily: 'Plus Jakarta Sans, sans-serif', fontWeight: 700, fontSize: 9, color: '#FFFCFF', lineHeight: 1 }}>
              {badge}
            </span>
          </div>
        )}
      </div>
      <span
        style={{
          fontFamily: 'Plus Jakarta Sans, sans-serif',
          fontWeight: 600,
          fontSize: 12,
          color: '#494150',
          lineHeight: 1.32,
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap',
        }}
      >
        {label}
      </span>
    </button>
  );
}

/* ── Main Sidebar ────────────────────────────────────────────────────────── */

export function Sidebar({ screen }: SidebarProps) {
  return (
    <aside
      className="flex flex-col shrink-0 h-full overflow-y-auto overflow-x-hidden"
      style={{ width: 140, background: '#FFFCFF', borderRight: '1px solid #E7DFEE' }}
    >
      {/* Logo area */}
      <div style={{ background: '#FFFCFF', borderBottom: '1px solid #E7DFEE' }}>
        <IonicaLogo />
      </div>

      {/* Primary nav */}
      <nav className="flex flex-col">
        <NavItemRow label="Minha iônica" icon={<MinhaIonicaIcon />} active />
        <NavItemRow label="Estuda.com" icon={<EstudaIcon />} active={false} />
      </nav>

      {/* Spacer */}
      <div className="flex-1" />

      {/* Divider */}
      <div style={{ height: 1, background: '#E7DFEE', margin: '4px 0' }} />

      {/* Bottom nav */}
      <div className="flex flex-col px-1 pb-2 gap-0.5">
        <BottomNavItem label="Novidades" icon={<IcoBullhorn />} />
        <BottomNavItem label="Relatórios" icon={<IcoChartLine />} />
        <BottomNavItem label="Notificações" icon={<IcoBell />} badge={5} />
        <BottomNavItem label="Sair" icon={<IcoPowerOff />} />

        {/* Collapse button */}
        <button
          className="flex items-center justify-center w-full mt-1 py-2 border-0 bg-transparent cursor-pointer rounded-lg hover:bg-[#F6F0FB] transition-colors"
        >
          <svg width="15" height="15" viewBox="0 0 14.625 14.0625" fill="none">
            <path d={DSPaths.chevronsLeft} fill="#A096A9" />
          </svg>
        </button>
      </div>
    </aside>
  );
}

